g7.push(A.b(2,"La coma vocativa sirve para separar el vocativo (la persona a la que nos dirigimos) del resto de la oraci\xf3n.","com_q53",A.a([m,"Coma el\xedptica","Coma vocativa","Coma apositiva"],q),"La coma que se emplea para aislar el nombre de la persona o cosa a la que nos dirigimos se denomina:",p))
